from collections import Counter,deque
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]: seen[a][b]=True;q.append((a,b))
    return [[4 if g[i][j]==bg and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]
